package com.cpf.education.online.internalservice.controller;
import com.cpf.core.api.context.CpfContexts;import com.cpf.education.online.internalservice.service.EntryService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.web.api.CpfController;import io.swagger.v3.oas.annotations.Operation;import java.util.Map;import org.springframework.web.bind.annotation.*;
/** 동일 Application 내부 호출 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfController @RequestMapping("/edu/online/member-processing") public class MemberProcessingController {private final EntryService service;public MemberProcessingController(EntryService s){service=s;}@PostMapping @Operation(operationId="EDU_LOCAL_MEMBER_PROCESS",summary="동일 Application Service 호출") @CpfOnlineTransaction(operationId="EDU_LOCAL_MEMBER_PROCESS",name="동일 Application Service 호출",description="Self HTTP 없이 같은 JVM의 Service Bean을 직접 호출하고 CPF Context와 REQUIRED Transaction을 유지한다.") public Map<String,String> call(@RequestBody String value){String tx=CpfContexts.transactionId();return Map.of("transactionId",tx,"result",service.process(value));}}
